B="BK-741"
C=[
("S16",4461,4465,"التوقيع جزء من المستند له حجية خاصة","يفرق الكتاب بين متن المستند والتوقيعات، ويبين أن التوقيع أو الختم أو البصمة هو ما يربط المستند بصاحبه. لهذا يتركز عليه الطعن بالتزوير.","اسأل عن أي مستند: أين التوقيع؟ ومن شاهد التوقيع؟ وهل هناك شهود على لحظة التوقيع؟","وجود التوقيع لا يثبت أن صاحبه قرأ المستند أو وافق على كل ما فيه.","","16-18","safe","reporting",["KO-FC-04B-004","KO-RS-05-004"],["توقيع","حجية"]),
("S16",4466,4481,"أنماط التوقيع: كامل ومختزل ومزخرف، ولكل منها عادة ثابتة","يصنف الكتاب التوقيعات إلى كاملة الحروف، ومختزلة بسرعة، ومعها زخرفة ختامية، ويشير إلى أن التوقيع السريع المتكرر يحتاج نماذج مأخوذة في ظروف مماثلة. الزخرفة قد تكون عنصراً مهماً في المقارنة.","عند مقارنة توقيعين، اسأل: هل هما من النمط نفسه؟ وهل ظروف الكتابة متشابهة؟","التوقيع المختزل المتكرر يصعب إثبات فرق دقيق فيه.","","16-18","conceptual","lab_limits",["KO-FC-04B-004","KO-FC-04-017"],["توقيع مختزل","زخرفة"]),
("S16",4482,4495,"التوقيع الصحيح له تنوع طبيعي ضمن مدى محدود","يقول الكتاب إن توقيعات الشخص الواحد لا تتطابق تماماً بل تتنوع تنوعاً طبيعياً داخل مدى، وإن وجود هذا التنوع علامة طبيعية، بينما التطابق التام المتكرر يثير الشك. وللتوقيع الطبيعي طلاقة ونهايات متدرجة.","قارن بين عدة توقيعات صحيحة معروفة لتحدد مدى التنوع قبل الحكم على التوقيع المطعون فيه.","مدى التنوع يتسع عند البعض ويضيق عند آخرين، وحالة الصحة تؤثر.","التوقيع الصحيح دائماً نسخة طبق الأصل.","16-18","conceptual","lab_limits",["KO-FC-04B-004","KO-FC-04B-005"],["تنوع طبيعي","مدى"]),
("S16",4496,4517,"محاكاة التوقيع تترك علامات بطء وتردد","يشرح الكتاب أن من يقلد توقيعاً بالنظر يكتب ببطء ويرفع القلم في مواضع غير طبيعية فتتكسر الخطوط، وقد يخالف الأصل في تفاصيل الحروف. وإذا قلّد عدة مرات بدت التوقيعات متشابهة أكثر من اللازم. نكتفي بالمؤشرات دون أي إرشاد للتقليد.","في اللعبة: قارن توقيعاً سريعاً منسابا بتوقيع مرتعش متقطع وتعلم ما يدل عليه ذلك وما لا يدل.","الارتعاش قد يعود إلى مرض أو سن لا إلى التزوير.","كل توقيع بطيء مزور.","16-18","conceptual","lab_limits",["KO-FC-04B-004","KO-RS-05-007","KO-RS-06-004"],["بطء","مؤشر لا دليل"]),
("S16",4518,4561,"النقل الآلي للتوقيع يترك أثر ضغط أو تطابق زائد","يعرض الكتاب أن بعض أساليب النقل تترك آثار ضغط على الورق، أو بقايا مادة، أو تطابقاً تاماً مع توقيع أصلي. التصوير بالإضاءة المائلة والفحص المكبر يكشف هذه الآثار. المبدأ: ما يُنقل بآلة يحمل بصمة آلة النقل.","اسأل: هل يوجد توقيع أصلي مطابق تماماً؟ فالتطابق التام يوجه إلى النقل.","عدم وجود أثر لا ينفي التزوير، ووجود أثر يحتاج تفسيراً دقيقاً.","","18+","conceptual","lab_limits",["KO-FC-04B-004","KO-FC-04-019"],["أثر ضغط","تطابق تام"]),
("S16",4562,4564,"التوقيع غير الصحيح ليس بالضرورة مقلّداً","يذكر الكتاب فئة التوقيعات التي لم يكتبها صاحبها لكنها لا تحاكي توقيعه أصلاً، وقد تكون كتابة طبيعية أو متصنعة لإخفاء الكاتب. لذلك سؤال الفاحص ليس فقط هل هو مزور، بل من أي نوع من غير الصحيح هو.","وسّع أسئلتك: صحيح، مقلّد، أم من غير صاحبه من غير تقليد؟","وجود اختلاف عن نماذج المقارنة لا يعني وجود نية خداع.","","16-18","conceptual","reporting",["KO-FC-04B-004","KO-RS-06-006"],["غير صحيح","احتمالات"]),
("S16",4565,4588,"ست حالات للتوقيع تلخص منطق الفحص","يلخص الكتاب منطقاً شبه جدولي: كتابة طبيعية مع اتفاق، طبيعية مع خلاف، غير طبيعية مع تشابه شكلي وخلاف، وغير طبيعية بقصد الإخفاء، وغير طبيعية مع تطابق نقل. المبدأ أن النتيجة تجمع أكثر من عنصر، لا عنصراً واحداً.","ارسم جدولاً من محورين: طبيعية الكتابة، والاتفاق مع النماذج، واستنتج الاحتمالات منه.","الجدول تبسيط وتتداخل الحالات في الواقع، ولا يغني عن الخبرة.","","18+","conceptual","lab_limits",["KO-RS-06-006","KO-RS-06-001","KO-FC-04B-004"],["جدول قرار","تعدد عناصر"]),
("S16",4589,4612,"اليد المقادة واليد المعانة: كتابة بمساعدة قد تُنتج توقيعاً مطعوناً فيه","يتحدث الكتاب عن توقيع يكتب فيه شخص بيد غيره تقوده أو تعينه لضعف أو مرض. اليد المقادة يظهر فيها خليط من تكوينات قوية وضعيفة، واليد المعانة تظهر فيها اهتزاز مع بنية تتفق مع نماذج صاحبها. الفحص هنا يسأل عن صحة الإرادة لا عن الخط وحده.","اسأل: هل كان صاحب التوقيع واعياً ومريداً؟ فالخط وحده لا يجيب.","ظهور علامات المساعدة لا يثبت الإكراه ولا ينفيه.","","18+","sensitive","witness_reliability",["KO-RS-05-014","KO-RS-06-004"],["يد مقادة","إرادة"]),
("S16",4613,4647,"بصمة الختم الأصلية تحمل علامات القالب الصلب","يذكر الكتاب أن بصمة ختم معدني صلب تترك أثر ضغط وإطاراً محدداً وتجمعاً للحبر على حواف الخطوط، بينما المحاكاة اليدوية أو النقل أو القالب المقلد له علامات تفرقه. الفرق بين الأصل والمقلد يظهر في التفاصيل الدقيقة.","قارن بصمة ختم بنماذج مؤكدة، وانتبه للضغط والحواف قبل المقارنة بالشكل.","احتمال أن يملك أكثر من شخص القالب نفسه يضعف نسبة الختم لشخص بعينه.","الختم الصحيح يثبت أن صاحبه هو من وضعه.","16-18","conceptual","lab_limits",["KO-FC-04-016","KO-FC-04B-005","KO-RS-06-004"],["قالب","ضغط"]),
]
